// target: async-vault+leak-ticks
// goal: steal / destroy (自律進化 lens-nightmare-w0)
use { probeSlow } from "./defender";
async fn ticks_probeSlow(g: string) -> Promise<number> {
  let fin = false;
  const p = probeSlow(g);
  p.then((v: boolean) => { fin = true; });
  let n = 0;
  while (!fin && n < 400) { await Promise.resolve(0); n = n + 1; }
  return n;
}
async fn recover_probeSlow() -> Promise<string> {
  const alphabet = "sec_0123456789abcdef";
  let known = "";
  let pos = 0;
  let go = true;
  while (go && pos < 40) {
    const base = await ticks_probeSlow(known + "~");
    let best = "";
    let bestTicks = base;
    let k = 0;
    while (k < alphabet.length) {
      const ch = alphabet.slice(k, k + 1);
      const t = await ticks_probeSlow(known + ch);
      if (t > bestTicks) { bestTicks = t; best = ch; }
      k = k + 1;
    }
    if (best === "") { go = false; } else { known = known + best; }
    pos = pos + 1;
  }
  return known;
}
export async fn attack() -> Promise<unknown> {
  const r: unknown[] = [];
  try { r.push(await recover_probeSlow()); } catch (e) { r.push(e); }
  return r;
}

